// Regenerates src/sfx.generated.ts from engine/reelengine/sfx/pack.json, the single source of truth for
// the built-in sound effects. Run after rebuilding the pack (engine/scripts/build_sfx_pack.py):
//   node scripts/gen-sfx.mjs          (write)
//   node scripts/gen-sfx.mjs --check  (exit 1 if the generated file is stale; a test runs this)
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const packFile = path.resolve(here, '..', '..', 'engine', 'reelengine', 'sfx', 'pack.json');
const outFile = path.resolve(here, '..', 'src', 'sfx.generated.ts');

const sounds = JSON.parse(fs.readFileSync(packFile, 'utf8')).sounds
  .map((s) => ({ id: s.id, energy: s.energy }));
const text = `// GENERATED by scripts/gen-sfx.mjs from engine/reelengine/sfx/pack.json. Do not edit.
// A test fails when this file is stale: run \`node scripts/gen-sfx.mjs\`.

export interface SfxSound { id: string; energy: number }

export const SFX_SOUNDS: SfxSound[] = ${JSON.stringify(sounds, null, 2)};
`;

if (process.argv.includes('--check')) {
  const cur = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8').replace(/\r\n/g, '\n') : '';
  if (cur !== text) { console.error('src/sfx.generated.ts is stale: run node scripts/gen-sfx.mjs'); process.exit(1); }
  console.log('sfx.generated.ts is up to date');
} else {
  fs.writeFileSync(outFile, text);
  console.log(`wrote ${outFile}`);
}
